public class GeometryHelper {
    // 1. Access Modifier: public
    // 2. Class-level modifier: static
    // 3. Return Type: double
    // 4. Name: calculateCircleArea
    // 5. Parameter List: (double radius)
    public static double calculateCircleArea(double radius) {
        double pi = 3.1415926535;
        double area = pi * radius * radius;
        return area; // 6. Return statement matching return type double
    }

    public static void main(String[] args) {
        double r = 7.0;
        double result = calculateCircleArea(r);
        System.out.println("Radius: " + r);
        System.out.println("Area: " + result);
    }
}

