practiceProblems.solutionCode:
public class Main {
    public static int calcPerimeter(int width, int height) {
        return 2 * (width + height);
    }

    public static int calcArea(int width, int height) {
        return width * height;
    }

    public static void main(String[] args) {
        int w = 8, h = 5;
        System.out.println("Perimeter: " + calcPerimeter(w, h));
        System.out.println("Area: " + calcArea(w, h));
    }
}
